                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MPF_USER_DEPT_ASSO_V" ("EXT_USER_ID", "GENDER", "HIRED_DATE", "LEADER_EXT_USER_ID", "LEADER_SYNC_USER_ID", "LEADER_EXT_USER_NAME", "JOB_NUMBER", "TENANT_ID", "SYNC_USER_ID", "UNIONID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "EMAIL", "JOB_LEVEL_CODE", "JOB_LEVEL", "EXT_ORG_ID", "RELATED_TYPE", "IS_MAIN_ORG", "EXT_ORG_NAME", "PARENT_ID", "LAST_LOGIN_DATE", "IS_LEAVE", "PASSWORD", "BASE_DEPT_ID") AS     
  SELECT UO.USER_ID                                      AS EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                               
       UP.GENDER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       UO.HIRED_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       UO.LEADER_USER_ID                               AS LEADER_EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                          
       UO.LEADER_EXTRA_USER_ID                         AS LEADER_SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                         
       UO.LEADER_USER_NAME                             AS LEADER_EXT_USER_NAME,                                                                                                                                                                                                                                                                                                                                                                                                        
       UO.JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       UO.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       UO.EXTRA_USER_ID                                AS SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                
       UO.UNION_ID                                     AS UNIONID,                                                                                                                                                                                                                                                                                                                                                                                                                     
       UO.TITLE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       UO.NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       UO.AVATAR,                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       UO.STATE_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       UO.MOBILE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       UO.EMAIL,                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       NVL(UDP.JOB_LEVEL_CODE, 50)                     as JOB_LEVEL_CODE,                                                                                                                                                                                                                                                                                                                                                                                                              
       NVL(UDP.JOB_LEVEL, 'KEY_STAFF')                 as JOB_LEVEL,                                                                                                                                                                                                                                                                                                                                                                                                                   
       UO.DEPT_ID                                      AS EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                  
       decode(UO.MAIN_DEPT_ORDER, 0, 'MAIN', 'EXTRA')  AS RELATED_TYPE,                                                                                                                                                                                                                                                                                                                                                                                                                
       decode(UO.MAIN_DEPT_ORDER, 0, 1, 0)             AS IS_MAIN_ORG,                                                                                                                                                                                                                                                                                                                                                                                                                 
       NVL(SELECT_DEPT_NAME(UO.DEPT_ID), UO.DEPT_NAME) AS EXT_ORG_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                
       0                                               AS PARENT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                   
       UP.LAST_LOGIN_DATE,                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       UO.IS_LEAVE,                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       UP.PASSWORD,                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
FROM MPF_SHARE_BASIC_USER_INFO_V UO                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         LEFT JOIN BAO_USER_EXPAND UP ON UP.USER_ID = UO.USER_ID AND UP.BASE_DEPT_ID = UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                 
         LEFT JOIN BAO_USER_DEPT_EXPAND UDP                                                                                                                                                                                                                                                                                                                                                                                                                                            
                   ON UDP.USER_ID = UO.USER_ID and UDP.DEPT_ID = UO.DEPT_ID AND UDP.BASE_DEPT_ID = UO.BASE_DEPT_ID;                                                                                                                                                                                                                                                                                                                                                                    

